    $scope.GetVisitReasonNew = function (type, Orginactionid) {
        Orginactionid = Orginactionid || 0;
        var Org_id = 0;
        if (Orginactionid == 0) {
            Org_id = $scope.HospitalId;
        } else {
            Org_id = Orginactionid;
        }
        var getParams = {
            "OrganizationId": Org_id,
            "ReasonTypeId": 1,
            "SearchText": "",
            "VisitTypeId": null
        };
        eHnotePatientVisitReasonServices.GetOrganizationActiveAppointmentVisitReasonsById(getParams).then(function (resp) {
            if (resp.data !== undefined) {
                if (resp.data.status == "Success") {
                    var obj = {
                        "ActiveIND": "Y",
                        "Reason": "All Visit Reason",
                        "ReasonId": 0,
                        "ReasonTypeId": 1,
                        "Remarks": "",
                        "VisitReasonColorCode": "",
                        "VisitTypeId": 0,
                        "VisitTypeName": "",
                        "VisitiTypeCode": ""
                    };
                    $scope.AllVisitReasons = angular.copy(resp.data.rows) || [];
                    $scope.IsAppointmentVisitReasonInactive = false;
                    if ($scope.AllVisitReasons.length > 0) {
                        $scope.AllVisitReasons = $filter("filter")($scope.AllVisitReasons, function (item) {
                            return item.ActiveIND === 'Y';
                        });

                        $scope.AllVisitReasons.unshift(obj);
                        if (AppointmentDetailsCache.IsComingFrom == "Coordinator" && AppointmentDetailsCache.IsApptType == "PreAdmission") {
                            let type = AppointmentDetailsCache.SelectedAppointmentType || 0;
                            if (type == 1) {
                                $scope.AllVisitReasons = $filter("filter")($scope.AllVisitReasons, function (item) {
                                    return item.VisitTypeId === 3;
                                });
                            } else if (type == 2) {
                                $scope.AllVisitReasons = $filter("filter")($scope.AllVisitReasons, function (item) {
                                    return item.VisitTypeId === 3;
                                });
                            } else if (type == 3) {
                                $scope.AllVisitReasons = $filter("filter")($scope.AllVisitReasons, function (item) {
                                    return item.VisitTypeId === 3;
                                });
                            } else if (type == 4) {
                                $scope.AllVisitReasons = $filter("filter")($scope.AllVisitReasons, function (item) {
                                    return item.VisitTypeId === 4;
                                });
                            } else if (type == 6 || type == 7) {
                                $scope.AllVisitReasons = $filter("filter")($scope.AllVisitReasons, function (item) {
                                    return item.VisitTypeId === 6 || item.VisitTypeId === 7;
                                });
                            }
                            $scope.AllVisitReasons.unshift(obj);

                        }
                    }

                    if (type == "Get") {
                        //var visitfilter = $filter("filter")($scope.AllVisitReasons, { "ReasonId": $scope.selectedAppointmentObject.VisitReasonId }, true);
                        var visitfilter = $filter("filter")($scope.AllVisitReasons, { "ParentAppointmentVisitReasonId": $scope.selectedAppointmentObject.VisitReasonId }, true);
                        if (visitfilter.length > 0) {
                            $scope.selectedAppointmentObject.VisitReasonObj = visitfilter[0];
                        } else {
                            //As Discussed With Durga and Nimeshika Org Inactive visit reason scenario also allowing appointment update.
                            $scope.selectedAppointmentObject.VisitReasonObj = {};
                            //$scope.IsAppointmentVisitReasonInactive = false;
                            if ($scope.selectedAppointmentObject.VisitReasonName != '') {
                                if ($scope.pagename == "reschedule") {
                                    //$scope.IsAppointmentVisitReasonInactive = true;
                                    $scope.selectedAppointmentObject.VisitReasonObj.Reason = $scope.selectedAppointmentObject.VisitReasonName || '';

                                }
                            }
                            //$scope.selectedAppointmentObject.VisitReasonId = null;
                            //$scope.selectedAppointmentObject.VisitReasonName = "";
                            //$scope.selectedAppointmentObject.VisitReasonObj = "";
                        }
                    }

                    if (($scope.selectedAppointmentObject.AppointmentTypeId == 7 || $scope.selectedAppointmentObject.AppointmentTypeId == 6 || $scope.selectedAppointmentObject.AppointmentTypeId == 4) && ($scope.selectedAppointmentObject.VisitReasonObj != '')) {
                        $scope.onSelectVisitReason($scope.selectedAppointmentObject.VisitReasonObj);
                    }
                }
            }
        }, function (error) {
            console.log(error);
        });
    };


    $scope.searchReferalDoctors = function (val, typeid) {

        var searchtext = "", searchNPI = "";
        if (isNaN(val)) {
            searchtext = val;
        }
        else {
            searchNPI = val;
        }

        var param = {
            'LocationId': null,
            'PageNumber': 1,
            'PageSize': 1000,
            'SearchTaxt': searchtext,
            "SpecializationId": null,
            "DeleteInd": 'N',
            "NPI": searchNPI,
            "RefaralTypeId": typeid || 0,
            /*"OrganizationId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID*/
            "OrganizationId": $scope.HospitalId,
        };
        return eHnoteReferalDataService.GetReferalPCPDoctors(param).then(function (resp) {
            if (resp.data.count !== 0) {
                if (resp.data.PcpRefdetails.length > 0) {
                    $scope.ReferalDoctorsArray = resp.data.PcpRefdetails;  // <<< just this line added
                    return resp.data.PcpRefdetails.map(function (item) {
                        return item;
                    });
                }
            }
        }, function (error) {
            console.log(error);
        });
    }
