    /*new*/
    function calculateRequiredSlots(duration) {
        let MinPerCase = '';
        if ($scope.ApptDurationObj.DurationMinutes) {
            MinPerCase = parseInt($scope.ApptDurationObj.DurationMinutes) || 15;
        } else {
            //MinPerCase = $scope.selectedAppointmentObject.DocObj.MinPerCase || 15;
            MinPerCase = $scope.allUserAvailabilitySlots.MinPerCase  || 15;

        }
        return Math.ceil(duration / MinPerCase); // Number of 15-minute slots needed
    }

    // A slot with no PayorTypes configured is open to any payor. A slot with PayorTypes
    // configured is restricted to that list: Self Pay (paymentTypeObj.PaymentTypeId "1")
    // matches an entry with PayorId 0; insurance-based booking matches the patient's
    // selected primary insurance by OrganizationPayorId/PayorId.
    function IsSlotPayorAllowed(starttime) {
        // Only enforce payor matching for schedules actually configured as insurance-based —
        // the same gate filterSlotsByPayorType() uses to mark slots blocked in the grid. Without
        // this, a slot from a non-insurance-restricted schedule that happens to carry a
        // PayorTypes list (e.g. leftover/default data) got blocked on click even though the
        // grid itself never marked it unavailable, i.e. genuinely open slots got rejected.
        if (!$scope.selectedAppointmentObject.IsInsuranceBasedScheduling) {
            return true;
        }
        starttime = starttime || {};
        var payorTypes = starttime.PayorTypes || [];
        if (payorTypes.length === 0) {
            return true;
        }
        // Decide self-pay vs insurance from whether real insurance data is actually loaded
        // (SelectedPrimaryInsurance), not from paymentTypeObj.PaymentTypeId/IsPaymentTypeInd —
        // those two are set independently in several other code paths (e.g. the appointment-load
        // path that populates SelectedPrimaryInsurance only touches ShowHideInsuranceobj's copy of
        // this flag, not paymentTypeObj's), so PaymentTypeId can be stuck at "1" (self-pay) even
        // once a patient's real insurance — and its matching OrganizationPayorId — has loaded.
        var insurance = $scope.SelectedPrimaryInsurance;
        if (insurance && insurance !== "") {
            return payorTypes.some(function (p) {
                return (insurance.OrganizationPayorId && p.OrganizationPayorId === insurance.OrganizationPayorId) ||
                    (insurance.PayorId && p.PayorId === insurance.PayorId);
            });
        }
        // No insurance loaded/selected — self-pay; the slot must explicitly allow it (PayorId 0).
        return payorTypes.some(function (p) { return (p.PayorId || 0) === 0; });
    }

    // Re-checks the currently selected slot against the patient's payor once it becomes
    // known (or changes) after the slot was already chosen — e.g. a slot pre-selected from
    // a calendar, where the patient (and their payor) is only picked afterwards.
    $scope.ValidateSelectedSlotAgainstPayor = function () {
        if (!$scope.selectedAppointmentObject.StartTime) { return; }
        var slot = _.find($scope.selectedAppointmentObject.TimeSlotsStartArray, { StartTime: $scope.selectedAppointmentObject.StartTime });
        if (!slot) { return; }
        if (!IsSlotPayorAllowed(slot)) {
            alertify.error("Slot not available. Please unblock a slot and continue");

            $scope.isAppValiddities.isEnableAlertType = true;
            $scope.isAppValiddities.isValidOptionSelected = false;
            $scope.isAppValiddities.UnblockSlots = true;
            $scope.isAppValiddities.IsEnabledAfterCheckHere = false;
            $scope.isAppValiddities.BlockedSlotObj = slot;
            $scope.isAppValiddities.MaxApptError = false;
            $scope.isAppValiddities.IsfocusinNotes = false;
            $scope.isAppValiddities.MaxApptErrorMsgShow = false;
        }
    };

