                        $scope.isAppValiddities.MaxApptUnblock = false;
                        $scope.isAppValiddities.IsfocusinNotes = false;
                        $scope.isAppValiddities.MaxApptErrorMsgShow = false;
                        $scope.isAppValiddities.BlockedSlotObj = starttime;

