    function compareTime(str1, str2) {
        var time1 = str1;
        var time2 = str2;

        function getTimeAsNumberOfMinutes(time) {
            var timeParts = time.split(":");

            var timeInMinutes = (timeParts[0] * 60) + timeParts[1];

            return timeInMinutes;
        }
        var time1InMinutesForTime1 = getTimeAsNumberOfMinutes(time1);
        var time1InMinutesForTime2 = getTimeAsNumberOfMinutes(time2);



        var result = false;
        if (time1InMinutesForTime1 === time1InMinutesForTime2) {
            result = true;
        }
        return result;
    }


    function GetCalenarScreenslotsrestriction() {
        var starttime = $filter('date')(new Date($scope.Doctorcalendarobj.Starttime), 'HH:mm') || "";
        if (starttime != "") {
            if ($scope.selectedAppointmentObject.TimeSlotsStartArray.length > 0) {
                var filteredArray = $filter('filter')($scope.selectedAppointmentObject.TimeSlotsStartArray, { "StartTime": starttime }, true) || [];
                if (filteredArray.length > 0) {
                    $scope.Endtimechange1(filteredArray[0], $scope.selectedAppointmentObject);
                }
            }
        }

    }

    function overlaps(slotStart, slotEnd, bookedStart, bookedEnd) {
        var s1 = timeToMinutes(slotStart);
        var e1 = timeToMinutes(slotEnd);
        var s2 = timeToMinutes(bookedStart);
        var e2 = timeToMinutes(bookedEnd);

        // overlap if ranges intersect
        return s1 < e2 && e1 > s2;
    }
    /*new*/
    function restructureAvailabiliyandDoctorSlots(resp) {

        $scope.dateObject = new Date($scope.selectedAppointmentObject.AppointmentDate);
        var appointmentDate = $filter('date')($scope.dateObject, "yyyy-MM-dd");
        console.log(appointmentDate);

        var MinperCase = $scope.selectedAppointmentObject.DocObj.MinPerCase || 15;
        $scope.allUserAvailabilitySlots = {
            "SlotDate": appointmentDate,
            "StartTime": "00:00",
            "EndTime": "23:59",
            "MinPerCase": MinperCase
        };

        console.log(resp.UserScheduleSlots);
        if (resp.UserScheduleSlots.length > 0) {
            if (resp.UserScheduleSlots[0].MinPerCase != undefined) {
                // FIX 12: Always use MinPerCase for grid step.
                // DurationMinutes is per-slot (advanced), not the grid interval.
                $scope.allUserAvailabilitySlots.MinPerCase = parseInt(resp.UserScheduleSlots[0].MinPerCase, 10) || 15;

                $scope.allUserAvailabilitySlots.StartTime = angular.copy(resp.UserScheduleSlots[0].StartTime);
                $scope.allUserAvailabilitySlots.EndTime = angular.copy(resp.UserScheduleSlots[0].EndTime);
                $scope.allUserAvailabilitySlots.SlotDate = angular.copy(resp.UserScheduleSlots[0].SlotDate);
            }
            $scope.selectedAppointmentObject.IsInsuranceBasedScheduling = angular.copy(resp.UserScheduleSlots[0].IsInsuranceBasedScheduling) || false;
        }

        $scope.timeslots = [];
        $scope.availableSlots = [];
        $scope.Breaktimeslots = [];
        $scope.BreakIntervals = [];

$scope.iscurrentDate = false;
var givenMoment = moment($scope.allUserAvailabilitySlots.SlotDate, ["YYYY-MM-DD", "MM-DD-YYYY"]).startOf('day');
var currentMoment = moment().startOf('day');

if (givenMoment.isAfter(currentMoment)) {
    $scope.iscurrentDate = false;
} else {
    $scope.iscurrentDate = true;
}
        $scope.time = $filter('date')(new Date(), 'HH:mm');

        // Breaks are resolved first: the grid below renders them as blocks of their own.
        buildBreakSlots(resp);

        // ===== BUILD TIMESLOTS =====
        var token = 1;
        var dayStartArr = $scope.allUserAvailabilitySlots.StartTime.split(':');
        var dayEndArr = $scope.allUserAvailabilitySlots.EndTime.split(':');
        var dayStart = moment().hours($.trim(dayStartArr[0])).minutes($.trim(dayStartArr[1]));
        var dayEnd = moment().hours($.trim(dayEndArr[0])).minutes($.trim(dayEndArr[1]));

        var minPerCase = parseInt($scope.allUserAvailabilitySlots.MinPerCase) || 15;

        function makeBlockedSlot(startStr, endStr, durationMinutes, maxOverAllSlots) {
            var blockedSlot = {
                "StartTime": startStr,
                "EndTime": endStr,
                "DurationMinutes": durationMinutes,
                "MaxNumberOfSlots": 0,
                "TokenNumber": token++,
                "Available": "N",
                "IsBooked": false,
                "Count": 0,
                "OverallCount": resp.DoctorAppointmentCount || 0,
                "MaximumOverAllSlots": maxOverAllSlots || 0,
                "VisitReasons": []
            };
            blockedSlot.seqStartTime = startStr.replace(":", "");
            blockedSlot.seqEndTime = endStr.replace(":", "");
            blockedSlot.NewStartTime = $filter('date')($scope.allUserAvailabilitySlots.SlotDate + "T" + startStr, "hh:mm a");
            return blockedSlot;
        }

        // Renders the stretch between two configured slots as blocked blocks, at the same
        // granularity it was set up with in Manage Users > Time Slots: one block per break
        // slot, and a single block for anything left uncovered. It is deliberately NOT cut
        // into MinPerCase pieces — that produced 12:30, 12:45, 01:00 ... for one long break.
        function fillGapWithBreakBlocks(gapStart, gapEnd, maxOverAllSlots) {
            var gapStartMin = (gapStart.hours() * 60) + gapStart.minutes();
            var gapEndMin = (gapEnd.hours() * 60) + gapEnd.minutes();
            if (gapEndMin <= gapStartMin) { return; }

            var breaksInGap = [];
            angular.forEach($scope.BreakIntervals, function (b) {
                if (b.EndMinutes > gapStartMin && b.StartMinutes < gapEndMin) {
                    breaksInGap.push(b);
                }
            });
            breaksInGap.sort(function (a, b) { return a.StartMinutes - b.StartMinutes; });

            var cursorMin = gapStartMin;
            angular.forEach(breaksInGap, function (b) {
                var breakStart = Math.max(b.StartMinutes, cursorMin);
                var breakEnd = Math.min(b.EndMinutes, gapEndMin);
                if (breakEnd <= breakStart) { return; }

                // Stretch before this break that no break covers
                if (breakStart > cursorMin) {
                    $scope.timeslots.push(makeBlockedSlot(minutesToTime(cursorMin), minutesToTime(breakStart),
                        breakStart - cursorMin, maxOverAllSlots));
                }
                $scope.timeslots.push(makeBlockedSlot(minutesToTime(breakStart), minutesToTime(breakEnd),
                    breakEnd - breakStart, maxOverAllSlots));
                cursorMin = breakEnd;
            });

            if (cursorMin < gapEndMin) {
                $scope.timeslots.push(makeBlockedSlot(minutesToTime(cursorMin), minutesToTime(gapEndMin),
                    gapEndMin - cursorMin, maxOverAllSlots));
            }
        }

        if (resp.UserScheduleSlots && resp.UserScheduleSlots.length > 0) {
            var daySchedule = resp.UserScheduleSlots[0];

            if (daySchedule.SlotsList && daySchedule.SlotsList.length > 0) {

                // ===== NEW APPROACH: Build from SlotsList (Advanced Schedule) =====
                var advancedSlots = [];
                angular.forEach(daySchedule.SlotsList, function (scheduleSlot) {
                    if (scheduleSlot.DeleteInd === "Y") return;

                    var arr = scheduleSlot.StartTime.split(':');
                    var startMoment = moment().hours($.trim(arr[0])).minutes($.trim(arr[1]));

                    // DurationMinutes only comes back from GetDoctorAvaiableSlotByDate. On the
                    // GetDoctorAvaiableDatesandSlots payload it's absent, so fall back to the
                    // StartTime/EndTime the slot was configured with.
                    var slotDuration = parseInt(scheduleSlot.DurationMinutes, 10);
                    if (!slotDuration || slotDuration <= 0) {
                        slotDuration = timeToMinutes(normalizeTime(scheduleSlot.EndTime))
                            - timeToMinutes(normalizeTime(scheduleSlot.StartTime));
                    }
                    if (!slotDuration || slotDuration <= 0) { slotDuration = minPerCase; }

                    var endMoment = startMoment.clone().add(slotDuration, 'minute');

                    advancedSlots.push({
                        "StartTime": scheduleSlot.StartTime,
                        "EndTime": endMoment.format("HH:mm"),
                        "DurationMinutes": slotDuration,
                        "MaxNumberOfSlots": scheduleSlot.MaxNumberOfSlots || 0,
                        "Available": "Y",
                        "VisitReasons": scheduleSlot.VisitReasons || [],
                        "PayorTypes": scheduleSlot.PayorTypes || [],
                        "startMoment": startMoment,
                        "endMoment": endMoment
                    });
                });

                advancedSlots.sort(function (a, b) {
                    return a.StartTime.localeCompare(b.StartTime);
                });

                // Build grid: gaps (blocked) + advanced slots (available)
                var cursor = angular.copy(dayStart);

                angular.forEach(advancedSlots, function (advSlot) {
                    // Fill gap BEFORE this advanced slot with break/blocked blocks
                    fillGapWithBreakBlocks(cursor, advSlot.startMoment, daySchedule.MaximumOverAllSlots);

                    // Add the advanced slot (AVAILABLE)
                    var availSlot = {
                        "StartTime": advSlot.StartTime,
                        "EndTime": advSlot.EndTime,
                        "DurationMinutes": advSlot.DurationMinutes,
                        "MaxNumberOfSlots": advSlot.MaxNumberOfSlots,
                        "TokenNumber": token++,
                        "Available": "Y",
                        "IsBooked": false,
                        "Count": 0,
                        "OverallCount": resp.DoctorAppointmentCount || 0,
                        "MaximumOverAllSlots": daySchedule.MaximumOverAllSlots || 0,
                        "VisitReasons": advSlot.VisitReasons,
                        "PayorTypes": advSlot.PayorTypes || []
                    };
                    availSlot.seqStartTime = availSlot.StartTime.replace(":", "");
                    availSlot.seqEndTime = availSlot.EndTime.replace(":", "");
                    var datetime = $scope.allUserAvailabilitySlots.SlotDate + "T" + availSlot.StartTime;
                    availSlot.NewStartTime = $filter('date')(datetime, "hh:mm a");
                    $scope.timeslots.push(availSlot);

                    // Move cursor to end of this advanced slot
                    cursor = advSlot.endMoment;
                });

                // Fill remaining gap after last advanced slot until day end
                fillGapWithBreakBlocks(cursor, dayEnd, daySchedule.MaximumOverAllSlots);

            } else {

                // ===== OLD APPROACH: No SlotsList, generate from StartTime/EndTime =====
                var currentStartTime = angular.copy(dayStart);
                while (currentStartTime < dayEnd) {
                    var slotObj = {
                        "StartTime": currentStartTime.format("HH:mm"),
                        "EndTime": currentStartTime.clone().add(minPerCase, "minute").format("HH:mm"),
                        "TokenNumber": token,
                        "Available": "N",
                        "IsBooked": false,
                        "Count": 0,
                        "MaxNumberOfSlots": 0,
                        "OverallCount": resp.DoctorAppointmentCount || 0,
                        "MaximumOverAllSlots": daySchedule.MaximumOverAllSlots || 0
                    };
                    token++;
                    slotObj.seqStartTime = slotObj.StartTime.replace(":", "");
                    slotObj.seqEndTime = slotObj.EndTime.replace(":", "");
                    var datetime = $scope.allUserAvailabilitySlots.SlotDate + "T" + slotObj.StartTime;
                    slotObj.NewStartTime = "";
                    slotObj.NewStartTime = $filter('date')(datetime, "hh:mm a");
                    $scope.timeslots.push(slotObj);
                    currentStartTime.add(minPerCase, "minute");
                }
            }
        } else {
            // No schedule at all for this date (e.g. the doctor's schedule doesn't cover this
            // month) — still render a full day of blocked slots using the default 00:00-23:59 grid,
            // matching how a scheduled day with no matching slots renders, instead of leaving the
            // "Available Slots" panel empty.
            var currentStartTime = angular.copy(dayStart);
            while (currentStartTime < dayEnd) {
                var slotObj = {
                    "StartTime": currentStartTime.format("HH:mm"),
                    "EndTime": currentStartTime.clone().add(minPerCase, "minute").format("HH:mm"),
                    "TokenNumber": token,
                    "Available": "N",
                    "IsBooked": false,
                    "Count": 0,
                    "MaxNumberOfSlots": 0,
                    "OverallCount": resp.DoctorAppointmentCount || 0,
                    "MaximumOverAllSlots": 0
                };
                token++;
                slotObj.seqStartTime = slotObj.StartTime.replace(":", "");
                slotObj.seqEndTime = slotObj.EndTime.replace(":", "");
                var datetime = $scope.allUserAvailabilitySlots.SlotDate + "T" + slotObj.StartTime;
                slotObj.NewStartTime = $filter('date')(datetime, "hh:mm a");
                $scope.timeslots.push(slotObj);
                currentStartTime.add(minPerCase, "minute");
            }
        }

        // ===== DEDUPLICATE TIMESLOTS =====
        var uniqueTimeslots = [];
        var seenStartTimes = {};
        angular.forEach($scope.timeslots, function (slot) {
            if (!seenStartTimes[slot.StartTime]) {
                seenStartTimes[slot.StartTime] = true;
                uniqueTimeslots.push(slot);
            }
        });
        $scope.timeslots = uniqueTimeslots;

        // Filter out past times if current date
        if ($scope.iscurrentDate === true) {
            $scope.timeslots = $filter("filter")($scope.timeslots, function (kitem) {
                return kitem.StartTime > $scope.time;
            });
        }

        // ===== BUILD AVAILABLESLOTS =====
        $scope.availableSlots = [];

        // Check if we have advanced slots with VisitReasons
        var hasAdvancedVisitReasons = false;
        angular.forEach($scope.timeslots, function (timeSlot) {
            if (timeSlot.VisitReasons && timeSlot.VisitReasons.length > 0) {
                hasAdvancedVisitReasons = true;
            }
        });

        if (hasAdvancedVisitReasons) {
            // NEW APPROACH: Build from VisitReasons in each timeslot
            angular.forEach($scope.timeslots, function (timeSlot) {
                if (timeSlot.VisitReasons && timeSlot.VisitReasons.length > 0) {
                    angular.forEach(timeSlot.VisitReasons, function (vr) {
                        if (vr.DeleteInd !== "Y") {
                            var availSlot = {
                                "StartTime": timeSlot.StartTime,
                                "EndTime": timeSlot.EndTime,
                                "DurationMinutes": timeSlot.DurationMinutes,
                                "MaxNumberOfSlots": timeSlot.MaxNumberOfSlots,
                                "IsSlotAvailable": true,
                                "VisitReasonId": vr.ReasonId,
                                "VisitReasonName": vr.Reason,
                                "Count": 0,
                                "IsBooked": false,
                                "Available": "Y",
                                "OverallCount": resp.DoctorAppointmentCount || 0,
                                "MaximumOverAllSlots": timeSlot.MaximumOverAllSlots || 0,
                                "PayorTypes": timeSlot.PayorTypes || []
                            };
                            $scope.availableSlots.push(availSlot);
                        }
                    });
                }
            });
        } else {
            // OLD APPROACH: Build availableSlots for all timeslots (no visit reason filtering)
            if (resp.UserScheduleSlots.length > 0) {
                var scheduleItem = resp.UserScheduleSlots[0];
                scheduleItem.ScheduleVisitTypeDetails = scheduleItem.ScheduleVisitTypeDetails || [];

                angular.forEach($scope.timeslots, function (timeSlot) {
                    if (scheduleItem.ScheduleVisitTypeDetails.length > 0) {
                        // Has visit type restrictions from old schedule
                        angular.forEach(scheduleItem.ScheduleVisitTypeDetails, function (vtd) {
                            var availSlot = {
                                "StartTime": timeSlot.StartTime,
                                "EndTime": timeSlot.EndTime,
                                "DurationMinutes": minPerCase,
                                "MaxNumberOfSlots": scheduleItem.MaximumOverAllSlots || 0,
                                "IsSlotAvailable": true,
                                "VisitReasonId": vtd.VisitReasonId || 0,
                                "VisitReasonName": vtd.VisitReasonName || "",
                                "Count": 0,
                                "IsBooked": false,
                                "Available": "Y",
                                "OverallCount": resp.DoctorAppointmentCount || 0,
                                "MaximumOverAllSlots": scheduleItem.MaximumOverAllSlots || 0
                            };
                            $scope.availableSlots.push(availSlot);
                        });
                    } else {
                        // No visit type restrictions — open to all
                        var availSlot = {
                            "StartTime": timeSlot.StartTime,
                            "EndTime": timeSlot.EndTime,
                            "DurationMinutes": minPerCase,
                            "MaxNumberOfSlots": scheduleItem.MaximumOverAllSlots || 0,
                            "IsSlotAvailable": true,
                            "VisitReasonId": 0,
                            "VisitReasonName": "",
                            "Count": 0,
                            "IsBooked": false,
                            "Available": "Y",
                            "OverallCount": resp.DoctorAppointmentCount || 0,
                            "MaximumOverAllSlots": scheduleItem.MaximumOverAllSlots || 0
                        };
                        $scope.availableSlots.push(availSlot);
                    }
                });
            }
        }

        // ===== HANDLE BREAK SLOTS =====
        // Declared here but called before the slot grid is built (function declarations are
        // hoisted), because the grid now renders each configured break as its own block.
        function buildBreakSlots(resp) {
        if (resp.UserScheduleSlots.length > 0) {
            $scope.isAppValiddities.UserScheduleId = resp.UserScheduleSlots[0].UserScheduleId;

            // FIX 5: Breaktimeslots reset is here ONCE, BEFORE the loop
            // (already set to [] at top, but explicit for clarity)

            angular.forEach(resp.UserScheduleSlots, function (item) {
                item.ScheduleVisitTypeDetails = item.ScheduleVisitTypeDetails || [];
                // FIX 6: Guard against empty string — always fallback to 15
                if (!item.DurationMinutes) {
                    item.MinPerCase = parseInt(item.MinPerCase) || 15;
                } else {
                    item.MinPerCase = parseInt(item.DurationMinutes) || parseInt(item.MinPerCase) || 15;
                }

                // DO NOT reset $scope.Breaktimeslots here (was Bug 5)

                item.UserDayBlockedSlots = item.UserDayBlockedSlots || [];
                item.UserDayBreakSlots = $filter('filter')(item.UserDayBreakSlots, { "UserBranchId": item.UserBranchId }, true);

                // Remove scheduled break slot which is of type unblock
                angular.forEach(item.UserDayBlockedSlots, function (jitem) {
                    jitem.IsDelete = false;
                });
                angular.forEach(item.UserDayBreakSlots, function (hitem) {
                    hitem.IsDelete = false;
                });
                angular.forEach(item.UserDayBlockedSlots, function (jitem, index1) {
                    let arr = jitem.StartTime.split(":");
                    let s1 = arr[0] + ":" + arr[1];
                    jitem.StartTime = s1;

                    angular.forEach(item.UserDayBreakSlots, function (hitem, index2) {
                        if (jitem.Status === "Unblocked" && jitem.StartTime === hitem.StartTime) {
                            jitem.IsDelete = true;
                            hitem.IsDelete = true;
                        }
                    });
                });

                item.UserDayBreakSlots = $filter('filter')(item.UserDayBreakSlots, { "IsDelete": false }, true);
                item.UserDayBlockedSlots = $filter('filter')(item.UserDayBlockedSlots, { "IsDelete": false }, true);

                if (item.UserDayBlockedSlots.length > 0) {
                    angular.forEach(item.UserDayBlockedSlots, function (jitem) {
                        if (item.UserBranchId === jitem.UserBranchId) {
                            item.UserDayBreakSlots = item.UserDayBreakSlots || [];
                            item.UserDayBreakSlots.push(jitem);
                        }
                    });
                }

                if (item.UserDayBreakSlots.length > 0) {
                    // Keep the breaks as whole ranges as well. The grid renders one block per
                    // range (advanced schedule) and blanks out every grid start inside a range.
                    angular.forEach(item.UserDayBreakSlots, function (Bitem) {
                        var breakStartMin = timeToMinutes(normalizeTime(Bitem.StartTime));
                        var breakEndMin = timeToMinutes(normalizeTime(Bitem.EndTime));
                        if (breakEndMin > breakStartMin) {
                            $scope.BreakIntervals.push({
                                "StartTime": normalizeTime(Bitem.StartTime),
                                "EndTime": normalizeTime(Bitem.EndTime),
                                "StartMinutes": breakStartMin,
                                "EndMinutes": breakEndMin
                            });
                        }
                    });

                    angular.forEach(item.UserDayBreakSlots, function (Bitem) {
                        var arr = Bitem.StartTime.split(':');
                        var shour = $.trim(arr[0]);
                        var smin = $.trim(arr[1]);
                        var arr2 = Bitem.EndTime.split(':');
                        var ehour = $.trim(arr2[0]);
                        var emin = $.trim(arr2[1]);
                        var bStartTime = moment().hours(shour).minutes(smin);
                        var bEndTime = moment().hours(ehour).minutes(emin);

                        var currentStartTime = angular.copy(bStartTime);
                        var btoken = 1;
                                                // FIX 6: Guard against NaN/empty — always fallback to 15
                        var breakStep = parseInt(item.MinPerCase, 10) || 15;
                        while (currentStartTime < bEndTime) {
                            var slotObj = {
                                "StartTime": currentStartTime.format("HH:mm"),
                                "EndTime": currentStartTime.add(breakStep, "minute").format("HH:mm"),
                                "TokenNumber": btoken,
                                "Available": "N",
                                "IsBooked": false,
                                "MaxNumberOfSlots": item.MaximumOverAllSlots || 0,
                                "Count": 0,
                                "OverallCount": resp.DoctorAppointmentCount || 0,
                                "MaximumOverAllSlots": item.MaximumOverAllSlots || 0
                            };
                            btoken++;
                            slotObj.seqStartTime = slotObj.StartTime.replace(":", "");
                            slotObj.seqEndTime = slotObj.EndTime.replace(":", "");

                            var datetime = item.SlotDate + "T" + slotObj.StartTime;
                            slotObj.NewStartTime = "";
                            slotObj.NewStartTime = $filter('date')(datetime, "hh:mm a");

                            $scope.Breaktimeslots.push(slotObj);
                        }
                    });
                }
            });
        }
        }

        // ===== CHECK RESTRICT MULTIPLE SLOTS AND NORMAL SLOTS =====
        console.log($scope.selectedAppointmentObject.DocObj.RestrictMultipleSlots);

        if ($scope.availableSlots.length > 0 && resp.NormalSlots.length > 0) {
            if ($scope.selectedAppointmentObject.DocObj.RestrictMultipleSlots) {
                // Check if slots have per-slot max limits
                var hasPerSlotMax = false;
                angular.forEach($scope.availableSlots, function (slot) {
                    if (slot.MaxNumberOfSlots && slot.MaxNumberOfSlots > 0
                        && slot.MaxNumberOfSlots !== slot.MaximumOverAllSlots) {
                        hasPerSlotMax = true;
                    }
                });

                if (hasPerSlotMax) {
                    // Has per-slot max → grey out fully booked slots
                    var Array = checkSlotsAlreadyBooked($scope.availableSlots, resp.NormalSlots);
                    $scope.availableSlots = angular.copy(Array);
                } else {
                    // Only day-wise max → show as yellow (booked but still available)
                    var Array = checkSlotsAlreadyBookedWithYellow($scope.availableSlots, resp.NormalSlots);
                    $scope.availableSlots = angular.copy(Array);
                }
            } else {
                var Array = checkSlotsAlreadyBookedWithYellow($scope.availableSlots, resp.NormalSlots);
                $scope.availableSlots = angular.copy(Array);
            }
        }

        // ===== MATCH TIMESLOTS WITH AVAILABLESLOTS + BUILD TimeSlotsStartArray =====
        if ($scope.timeslots.length > 0) {
            // Step 1: Set Available on timeslots from availableSlots
            angular.forEach($scope.timeslots, function (item1) {
                var matches = $filter('filter')($scope.availableSlots, { "StartTime": item1.StartTime }, true);
                item1.Available = (matches.length > 0 && matches[0].Available === "Y") ? "Y" : "N";
            });

            // Step 2: Build TimeSlotsStartArray with metadata (break-slot blocking is inside)
            rebuildTimeSlotArrays(null);

            // A slot can already be selected here without going through Endtimechange1 — e.g. one
            // pre-filled from a calendar hand-off (Doctorcalendarobj), where the patient/payor is
            // already known by the time slots load. Re-check it now so the same "blocked slot" alert
            // used for a manual click also fires for that path, instead of silently letting it through.
            if ($scope.pagename !== 'reschedule') {
                $scope.ValidateSelectedSlotAgainstPayor();
            }
        }

        // ===== HANDLE RESCHEDULE PAGE =====
        if ($scope.pagename == 'reschedule') {
            $scope.selectedAppointmentObject.TimeSlotsStartArray = $scope.selectedAppointmentObject.TimeSlotsStartArray || [];
            var rtoken = $scope.selectedAppointmentObject.TimeSlotsStartArray.length + 1;
            var date_T = $filter("date")(new Date(), "yyyy-MM-dd");
            var datetime = date_T + "T" + $scope.selectedAppointmentObject.StartTime;
            var NewStartTime = "";
            NewStartTime = $filter('date')(datetime, "hh:mm a");

            // Find and mark existing slot
            var existingSlot = _.find($scope.selectedAppointmentObject.TimeSlotsStartArray, {
                StartTime: $scope.selectedAppointmentObject.StartTime
            });

            if (existingSlot) {
                // Slot exists in grid — mark it as selected
                existingSlot.Available = "Y";
                existingSlot.IsBooked = true;
                $scope.selectedAppointmentObject.SelectedTimeSlot = existingSlot;
            } else if ($scope.selectedAppointmentObject.StartTime != "") {
                // Slot not in grid — add it
                var slotObj = {
                    "StartTime": $scope.selectedAppointmentObject.StartTime,
                    "EndTime": $scope.selectedAppointmentObject.EndTime,
                    "NewStartTime": NewStartTime,
                    "TokenNumber": rtoken,
                    "Available": "Y",
                    "IsBooked": true,
                    "MaxNumberOfSlots": 0,
                    "Count": 0,
                    "OverallCount": 0,
                    "MaximumOverAllSlots": 0
                };
                $scope.selectedAppointmentObject.TimeSlotsStartArray.push(slotObj);
                $scope.selectedAppointmentObject.TimeSlotsEndArray.push(slotObj);
                $scope.selectedAppointmentObject.SelectedTimeSlot = slotObj;
            }

            // FIX 7: Highlight the reschedule slot range in teal
            angular.forEach($scope.selectedAppointmentObject.TimeSlotsStartArray, function (itemss) {
                var startTime = $scope.selectedAppointmentObject.StartTime;
                var endTime = $scope.selectedAppointmentObject.EndTime;

                var startTimeInt = parseInt(startTime.replace(":", ""));
                var endTimeInt = parseInt(endTime.replace(":", ""));

                var slotStartTimeInt = parseInt(itemss.StartTime.replace(":", ""));
                var slotEndTimeInt = parseInt((itemss.EndTime || "").replace(":", ""));

                if (slotEndTimeInt !== 0 && !isNaN(slotEndTimeInt)) {
                    if (slotStartTimeInt >= startTimeInt && slotEndTimeInt <= endTimeInt) {
                        itemss.isslotactiveind = true;
                    }
                }
            });

            // FIX 8: Enable unblock links
            $scope.selectedAppointmentObject.IsEnableUnblockedSlots = true;
        }

        // ===== HANDLE DOCTORCALENDAR BOOK (FIX 9) =====
        if ($scope.Doctorcalendarobj.IsComingFrom == 'Doctorcalendar' && $scope.pagename == 'book') {
            $scope.Doctorcalendarobj.OutOfBusinessTime = $scope.Doctorcalendarobj.OutOfBusinessTime || false;
            $scope.selectedAppointmentObject.TimeSlotsStartArray = $scope.selectedAppointmentObject.TimeSlotsStartArray || [];

            var ctoken = $scope.selectedAppointmentObject.TimeSlotsStartArray.length + 1;
            var cdate_T = $filter("date")(new Date(), "yyyy-MM-dd");
            var cNewStartTime = $filter('date')(cdate_T + "T" + $scope.selectedAppointmentObject.StartTime, "hh:mm a");
            $scope.selectedAppointmentObject.EndTime = $filter('date')(new Date($scope.Doctorcalendarobj.Endtime), 'HH:mm');

            if ($scope.selectedAppointmentObject.StartTime != "") {
                var exists = $filter('filter')($scope.selectedAppointmentObject.TimeSlotsStartArray,
                    { "StartTime": $scope.selectedAppointmentObject.StartTime }, true);
                if (exists.length == 0) {
                    var cSlot = {
                        "StartTime": $scope.selectedAppointmentObject.StartTime,
                        "EndTime": $scope.selectedAppointmentObject.EndTime,
                        "NewStartTime": cNewStartTime,
                        "TokenNumber": ctoken,
                        "Available": "Y",
                        "IsBooked": false,
                        "Count": 0,
                        "MaxNumberOfSlots": 0,
                        "OverallCount": 0,
                        "MaximumOverAllSlots": 0
                    };
                    if ($scope.Doctorcalendarobj.OutOfBusinessTime) {
                        $scope.isAppValiddities.isEnableAlertType = true;
                        $scope.isAppValiddities.isValidOptionSelected = false;
                        $scope.isAppValiddities.UnblockSlots = true;
                        $scope.isAppValiddities.IsfocusinNotes = true;
                        cSlot.Available = "N";
                    }
                    cSlot.seqStartTime = cSlot.StartTime.replace(":", "");
                    cSlot.seqEndTime = cSlot.EndTime.replace(":", "");
                    $scope.selectedAppointmentObject.TimeSlotsStartArray.push(cSlot);
                }
            }
            GetCalenarScreenslotsrestriction();
        }

        // ===== APPLY VISIT REASON FILTER IF ALREADY SELECTED =====
        if ($scope.selectedAppointmentObject.VisitReasonId) {
            $scope.onVisitReasonChange($scope.selectedAppointmentObject.VisitReasonId);
        }

        console.log("Final Timeslots:", $scope.timeslots);
        console.log("Final AvailableSlots:", $scope.availableSlots);
    }

    // ===== VISIT REASON CHANGE HANDLER =====
    $scope.onVisitReasonChange = function (visitReasonId) {
        console.log("Visit Reason Changed:", visitReasonId);

        // Step 1: BLOCK all slots first
        angular.forEach($scope.timeslots, function (slot) {
            slot.Available = "N";
            slot.InsuranceBlocked = false;
        });

        // Step 2: Check if we have visit-reason-based availableSlots
        var hasVisitReasonSlots = false;
        angular.forEach($scope.availableSlots, function (slot) {
            if (slot.VisitReasonId && slot.VisitReasonId !== 0) {
                hasVisitReasonSlots = true;
            }
        });

        if (!visitReasonId || !hasVisitReasonSlots) {
            // No visit reason selected OR old approach (no visit reason filtering)
            // Unblock all slots that have availableSlots entries
            angular.forEach($scope.timeslots, function (slot) {
                var matchedAvail = $filter('filter')($scope.availableSlots, { "StartTime": slot.StartTime }, true);
                if (matchedAvail.length > 0 && matchedAvail[0].Available == "Y") {
                    slot.Available = "Y";
                }
            });
        } else {
            // Step 3: Find slots with this visit reason
            var filteredSlots = $filter('filter')($scope.availableSlots, {
                "VisitReasonId": parseInt(visitReasonId)
            });

            // Try without parseInt if no match
            if (filteredSlots.length === 0) {
                filteredSlots = $filter('filter')($scope.availableSlots, {
                    "VisitReasonId": visitReasonId
                });
            }

            // Step 4: UNBLOCK only matching slots
            // If filteredSlots is empty, all slots stay BLOCKED (no fallback!)
            angular.forEach(filteredSlots, function (slot) {
                var fullSlot = _.find($scope.timeslots, {
                    StartTime: slot.StartTime
                });
                if (fullSlot) {
                    fullSlot.Available = "Y";
                }
            });
        }

        // Step 5: Insurance filtering
        if ($scope.selectedAppointmentObject.IsInsuranceBasedScheduling) {
            $scope.filterSlotsByPayorType();
        }

        // Step 6: REBUILD — uses rebuildTimeSlotArrays which:
        //   - Re-applies break-slot blocking
        //   - Copies metadata (IsBooked, Count, MaxNumberOfSlots) WITHOUT touching Available
        //   - Handles reschedule isslotactiveind + IsEnableUnblockedSlots
        rebuildTimeSlotArrays(visitReasonId);

        console.log("Updated TimeSlotsStartArray:", $scope.selectedAppointmentObject.TimeSlotsStartArray);
    };

    // ===== INSURANCE FILTER =====
    $scope.filterSlotsByPayorType = function () {

        var patientPayorTypeId = null;
        var isSelfPay = false;
        var appPayorId = 0;

        $scope.SelectedPrimaryInsurance = $scope.SelectedPrimaryInsurance || '';
        if ($scope.SelectedPrimaryInsurance != '') {
            appPayorId = $scope.SelectedPrimaryInsurance.PayorId || 0;
        }

        if (appPayorId != 0 && !$scope.paymentTypeObj.IsPaymentTypeInd) {
            patientPayorTypeId = appPayorId;
        } else {
            isSelfPay = true;
        }

        console.log("Patient PayorId:", patientPayorTypeId, "IsSelfPay:", isSelfPay);

        angular.forEach($scope.timeslots, function (slot) {
            if (slot.Available === "Y") {
                // No PayorTypes = "Open to All" → stays available
                if (!slot.PayorTypes || slot.PayorTypes.length === 0) {
                    return;
                }

                var isEligible = false;

                angular.forEach(slot.PayorTypes, function (pt) {
                    // Insurance patient: match by PayorId
                    if (!isSelfPay && patientPayorTypeId && pt.PayorId === patientPayorTypeId) {
                        isEligible = true;
                    }
                    // Self-pay patient: only match if slot explicitly allows self-pay
pt.PayorId=pt.PayorId||0;
                    if (isSelfPay && pt.PayorId==0) {
                        isEligible = true;
                    }
                });

                if (!isEligible) {
                    slot.Available = "N";
                    slot.InsuranceBlocked = true;
                }
            }
        });
    };
    function applySlotMetadata(item1, visitReasonId) {
        var matches = $filter('filter')($scope.availableSlots, { "StartTime": item1.StartTime }, true);
        var match = null;

        // FIX 11: Prefer the match with correct VisitReasonId
        if (matches.length > 0) {
            if (visitReasonId) {
                angular.forEach(matches, function (m) {
                    if (!match && m.VisitReasonId == visitReasonId) { match = m; }
                });
            }
            if (!match) { match = matches[0]; }
        }

        item1.IsCompletedMaxNumberofSlots = false;

        if (!match) {
            item1.IsBooked = false;
            item1.Count = 0;
            return;
        }

        // FIX 4: item1.Available is deliberately NOT touched here
        item1.IsBooked = match.IsBooked || false;
        item1.Count = match.Count || 0;
        item1.MaxNumberOfSlots = match.MaxNumberOfSlots || 0;
        item1.OverallCount = match.OverallCount || 0;
        item1.MaximumOverAllSlots = match.MaximumOverAllSlots || 0;

        // per-slot max reached
        if (item1.MaxNumberOfSlots !== 0 && item1.Count >= item1.MaxNumberOfSlots) {
            item1.IsCompletedMaxNumberofSlots = true;
        }
        // whole-day max reached
        if (item1.MaximumOverAllSlots !== 0 && item1.OverallCount >= item1.MaximumOverAllSlots) {
            item1.IsCompletedMaxNumberofSlots = true;
        }
        // a blocked slot is never yellow/red — matches old behaviour
        if (item1.Available !== "Y") {
            item1.IsBooked = false;
            item1.IsCompletedMaxNumberofSlots = false;
        }
    }

    function rebuildTimeSlotArrays(visitReasonId) {
        $scope.selectedAppointmentObject.TimeSlotsStartArray = [];
        $scope.selectedAppointmentObject.TimeSlotsEndArray = [];

        angular.forEach($scope.timeslots, function (item1) {
            var res = item1.StartTime.split(":");
            item1.StartTime = res[0] + ":" + res[1];

            // Break slots always win, re-applied on every rebuild
            if (isBreakSlot(item1.StartTime)) { item1.Available = "N"; }

            applySlotMetadata(item1, visitReasonId);

            $scope.selectedAppointmentObject.TimeSlotsStartArray.push(item1);
            $scope.selectedAppointmentObject.TimeSlotsEndArray.push(item1);
        });
        if ($scope.pagename == 'reschedule') {
            $scope.selectedAppointmentObject.TimeSlotsStartArray = $scope.selectedAppointmentObject.TimeSlotsStartArray || [];
            var rtoken = $scope.selectedAppointmentObject.TimeSlotsStartArray.length + 1;
            var date_T = $filter("date")(new Date(), "yyyy-MM-dd");
            var datetime = date_T + "T" + $scope.selectedAppointmentObject.StartTime;
            var NewStartTime = "";
            NewStartTime = $filter('date')(datetime, "hh:mm a");

            // Find and mark existing slot
            var existingSlot = _.find($scope.selectedAppointmentObject.TimeSlotsStartArray, {
                StartTime: $scope.selectedAppointmentObject.StartTime
            });

            if (existingSlot) {
                // Slot exists in grid — mark it as selected
                existingSlot.Available = "Y";
                existingSlot.IsBooked = true;
                $scope.selectedAppointmentObject.SelectedTimeSlot = existingSlot;
            } else if ($scope.selectedAppointmentObject.StartTime != "") {
                // Slot not in grid — add it
                var slotObj = {
                    "StartTime": $scope.selectedAppointmentObject.StartTime,
                    "EndTime": $scope.selectedAppointmentObject.EndTime,
                    "NewStartTime": NewStartTime,
                    "TokenNumber": rtoken,
                    "Available": "Y",
                    "IsBooked": true,
                    "MaxNumberOfSlots": 0,
                    "Count": 0,
                    "OverallCount": 0,
                    "MaximumOverAllSlots": 0
                };
                $scope.selectedAppointmentObject.TimeSlotsStartArray.push(slotObj);
                $scope.selectedAppointmentObject.TimeSlotsEndArray.push(slotObj);
                $scope.selectedAppointmentObject.SelectedTimeSlot = slotObj;
            }

            // FIX 7: Highlight the reschedule slot range in teal
            angular.forEach($scope.selectedAppointmentObject.TimeSlotsStartArray, function (itemss) {
                var startTime = $scope.selectedAppointmentObject.StartTime;
                var endTime = $scope.selectedAppointmentObject.EndTime;

                var startTimeInt = parseInt(startTime.replace(":", ""));
                var endTimeInt = parseInt(endTime.replace(":", ""));

                var slotStartTimeInt = parseInt(itemss.StartTime.replace(":", ""));
                var slotEndTimeInt = parseInt((itemss.EndTime || "").replace(":", ""));

                if (slotEndTimeInt !== 0 && !isNaN(slotEndTimeInt)) {
                    if (slotStartTimeInt >= startTimeInt && slotEndTimeInt <= endTimeInt) {
                        itemss.isslotactiveind = true;
                    }
                }
            });

            // FIX 8: Enable unblock links
            $scope.selectedAppointmentObject.IsEnableUnblockedSlots = true;
        }
        markRescheduleActiveSlot();
    }


    function markRescheduleActiveSlot() {
        if ($scope.pagename !== 'reschedule') { return; }

        var startInt = parseInt(($scope.selectedAppointmentObject.StartTime || "").replace(":", ""), 10);
        var endInt = parseInt(($scope.selectedAppointmentObject.EndTime || "").replace(":", ""), 10);
        if (isNaN(startInt) || isNaN(endInt)) { return; }

        angular.forEach($scope.selectedAppointmentObject.TimeSlotsStartArray, function (s) {
            s.isslotactiveind = false;
            var sS = parseInt(s.StartTime.replace(":", ""), 10);
            var sE = parseInt((s.EndTime || "").replace(":", ""), 10);
            if (!isNaN(sE) && sE !== 0 && sS >= startInt && sE <= endInt) {
                s.isslotactiveind = true;
            }
        });

        $scope.selectedAppointmentObject.IsEnableUnblockedSlots = true;
    }
