    function checkSlotsandSplice(array, bookedarray) {


        angular.forEach(bookedarray, function (item) {

            // new code for restrict slots that are already booke, slots with diff duration: sumanth
            let diff = parseInt(item.seqEndTime) - parseInt(item.seqStartTime);
            let tempSlotsArray = [];
            let patientConsultationTime = parseInt($scope.ApptDurationObj.consultationTime_for_restructure);
            if (item.seqEndTime !== "0000" && patientConsultationTime !== diff) {
                let arr = item.StartTime.split(':');
                let shour = $.trim(arr[0]);
                let smin = $.trim(arr[1]);
                let arr2 = item.EndTime.split(':');
                let ehour = $.trim(arr2[0]);
                let emin = $.trim(arr2[1]);
                let startingTime = moment().hours(shour).minutes(smin);
                let endingTime = moment().hours(ehour).minutes(emin);

                let currentStartTime = angular.copy(startingTime);

                while (currentStartTime < endingTime) {

                    let slotObj = {
                        "StartTime": currentStartTime.format("HH:mm"),
                        "EndTime": currentStartTime.add(patientConsultationTime, "minute").format("HH:mm"),
                    }

                    slotObj.seqStartTime = slotObj.StartTime.replace(":", "");
                    slotObj.seqEndTime = slotObj.EndTime.replace(":", "");

                    tempSlotsArray.push(slotObj);

                }
            }
            if (tempSlotsArray.length > 0) {
                angular.forEach(tempSlotsArray, function (kitem) {
                    for (var i = array.length - 1; i >= 0; i--) {
                        if (kitem.StartTime === array[i].StartTime) {
                            array.splice(i, 1);
                            //array[i].Available = 'N';
                        }
                    }
                });
            } else {
                for (var i = array.length - 1; i >= 0; i--) {
                    if (item.StartTime === array[i].StartTime) {
                        array.splice(i, 1);
                        //array[i].Available = 'N';
                    }
                }
            }

        });



        return array;
    }

    function checkSlotsAlreadyBooked(array, bookedarray) {
        angular.forEach(bookedarray, function (item) {
            var bookedStart = timeToMinutes(item.StartTime);
            var bookedEnd = timeToMinutes(item.EndTime);

            if (item.DurationMinutes && parseInt(item.DurationMinutes, 10) > 0) {
                bookedEnd = bookedStart + parseInt(item.DurationMinutes, 10);
            }
            if (bookedEnd <= bookedStart) { bookedEnd = bookedStart + 1; }

            angular.forEach(array, function (slot) {
                var slotStart = timeToMinutes(slot.StartTime);
                // FIX 1: < not <= (boundary slot is the NEXT slot, not part of this booking)
                if (slotStart >= bookedStart && slotStart < bookedEnd) {
                    slot.Available = 'N';
                }
            });
        });

        return array;
    }
    function timeToMinutes(t) {
        if (!t) return 0;

        var parts = t.split(':');
        return (parseInt(parts[0], 10) * 60) + parseInt(parts[1], 10);
    }
    function minutesToTime(m) {
        m = Math.max(0, parseInt(m, 10) || 0);
        var h = Math.floor(m / 60);
        var mi = m % 60;
        return (h < 10 ? "0" + h : "" + h) + ":" + (mi < 10 ? "0" + mi : "" + mi);
    }
    function isBreakSlot(startTime) {
        // Range based: a break configured as 12:30-13:00 blocks every grid start inside it,
        // even when the grid step doesn't land on the break boundaries.
        var mins = timeToMinutes(startTime);
        var intervals = $scope.BreakIntervals || [];
        for (var i = 0; i < intervals.length; i++) {
            if (mins >= intervals[i].StartMinutes && mins < intervals[i].EndMinutes) { return true; }
        }
        $scope.Breaktimeslots = $scope.Breaktimeslots || [];
        for (var j = 0; j < $scope.Breaktimeslots.length; j++) {
            if ($scope.Breaktimeslots[j].StartTime === startTime) { return true; }
        }
        return false;
    }
    function normalizeTime(t) {
        if (!t) return '';
        return t.length === 5 ? t : t.substring(0, 5);
    }
    function checkSlotsAlreadyBookedWithYellow(array, bookedarray) {
        angular.forEach(bookedarray, function (item) {
            var bookedStart = timeToMinutes(item.StartTime);
            var bookedEnd = timeToMinutes(item.EndTime);

            if (item.DurationMinutes && parseInt(item.DurationMinutes, 10) > 0) {
                bookedEnd = bookedStart + parseInt(item.DurationMinutes, 10);
            }
            if (bookedEnd <= bookedStart) { bookedEnd = bookedStart + 1; }

            angular.forEach(array, function (slot) {
                var slotStart = timeToMinutes(slot.StartTime);

                // FIX 1: < not <= (10:10-10:20 booking should NOT mark 10:20 slot)
                if (slotStart >= bookedStart && slotStart < bookedEnd) {
                    slot.IsBooked = true;
                    // FIX 2: Increment Count so IsCompletedMaxNumberofSlots can trigger
                    slot.Count = (slot.Count || 0) + (parseInt(item.Count, 10) || 1);
                }
            });
        });

        return array;
    }

