            //$scope.ReplaceASCTemplateItems();
            let docId = $scope.selectedAppointmentObject?.DoctorID || 0;
            $scope.OrderInit('', docId);
            let DeleteCheck = $filter("filter")($scope.SelectedNewSurgeries, function (Aitem, index) { return Aitem.DeleteInd == 'Y' },);
