    function InsuranceDropDownUpdates(item) {
        $scope.AddInsuranceToAppt = [];
        var ApptLevelPatientInsuranceList = item.PatientInsuranceList || [];
        if (ApptLevelPatientInsuranceList.length > 0) {
            // for insurance 
            if (ApptLevelPatientInsuranceList.length > 0) {
                // Assign the first element if it exists, otherwise assign an empty string
                const filteredInsurance1 = $filter('filter')(ApptLevelPatientInsuranceList, { 'IdentifierId': 1 }, true);
                $scope.SelectedPrimaryInsurance = filteredInsurance1.length > 0 ? filteredInsurance1[0] : "";
                const filteredInsurance2 = $filter('filter')(ApptLevelPatientInsuranceList, { 'IdentifierId': 2 }, true);
                $scope.SelectedsecondaryInsurance = filteredInsurance2.length > 0 ? filteredInsurance2[0] : "";
                const filteredInsurance3 = $filter('filter')(ApptLevelPatientInsuranceList, { 'IdentifierId': 5 }, true);
                $scope.SelectedOtherInsurance = filteredInsurance3.length > 0 ? filteredInsurance3[0] : "";
                $scope.ShowHideInsuranceobj.IsPaymentTypeInd = false;
            } else {
                $scope.SelectedPrimaryInsurance = '';
                $scope.SelectedsecondaryInsurance = '';
                $scope.SelectedOtherInsurance = '';
                $scope.paymentTypeObj.IsPaymentTypeInd = true;
                $scope.ShowHideInsuranceobj.IsPaymentTypeInd = true;
            }
            if ($scope.SelectedPrimaryInsurance != '') {
                $scope.ShowHideInsuranceobj.PrimaryInusrancePlanName = angular.copy($scope.SelectedPrimaryInsurance.PlanName) || "";
                $scope.ShowHideInsuranceobj.PrimaryInusrancePolicyId = angular.copy($scope.SelectedPrimaryInsurance.PolicyId) || "";
                $scope.ShowHideInsuranceobj.PrimaryInusranceCoverage = angular.copy($scope.SelectedPrimaryInsurance.PayorName) || "";
                $scope.ShowHideInsuranceobj.PrimaryInusranceGroupId = angular.copy($scope.SelectedPrimaryInsurance.GroupId) || "";
                $scope.ShowHideInsuranceobj.IsPrimaryInsuranceInd = true;
                $scope.PushAddInsuranceToAppt($scope.SelectedPrimaryInsurance);
            }
            else {
                $scope.ShowHideInsuranceobj.IsPrimaryInsuranceInd = false;
            }
            if ($scope.SelectedsecondaryInsurance != '') {
                $scope.ShowHideInsuranceobj.SecondInusrancePlanName = angular.copy($scope.SelectedsecondaryInsurance.PlanName) || "";
                $scope.ShowHideInsuranceobj.SecondInusrancePolicyId = angular.copy($scope.SelectedsecondaryInsurance.PolicyId) || "";
                $scope.ShowHideInsuranceobj.SecondInusranceCoverage = angular.copy($scope.SelectedsecondaryInsurance.PayorName) || "";
                $scope.ShowHideInsuranceobj.SecondInusranceGroupId = angular.copy($scope.SelectedsecondaryInsurance.GroupId) || "";
                $scope.ShowHideInsuranceobj.IsSecondaryInsuranceInd = true;
                $scope.PushAddInsuranceToAppt($scope.SelectedsecondaryInsurance);
            }
            else {
                $scope.ShowHideInsuranceobj.IsSecondaryInsuranceInd = false;
            }
            if ($scope.SelectedOtherInsurance != '') {
                $scope.ShowHideInsuranceobj.OtherInusrancePlanName = angular.copy($scope.SelectedOtherInsurance.PlanName) || "";
                $scope.ShowHideInsuranceobj.OtherInusrancePolicyId = angular.copy($scope.SelectedOtherInsurance.PolicyId) || "";
                $scope.ShowHideInsuranceobj.OtherInusranceCoverage = angular.copy($scope.SelectedOtherInsurance.PayorName) || "";
                $scope.ShowHideInsuranceobj.OtherInusranceGroupId = angular.copy($scope.SelectedOtherInsurance.GroupId) || "";
                $scope.ShowHideInsuranceobj.IsotherInsuranceInd = true;
                $scope.PushAddInsuranceToAppt($scope.SelectedOtherInsurance);
            } else {
                $scope.ShowHideInsuranceobj.IsotherInsuranceInd = false;
            }
            // for the Insurance delete icon desible
            if ($scope.InsuranceList.PatientInsuranceDetails.length > 0 && ApptLevelPatientInsuranceList.length > 0) {
                angular.forEach($scope.InsuranceList.PatientInsuranceDetails, function (aitem) {
                    var filteritem = $filter('filter')(ApptLevelPatientInsuranceList, { 'patientInsuranceDetailId': aitem.patientInsuranceDetailId }, true) || [];
                    if (filteritem.length > 0) {
                        aitem.IsInsuranceConnectedAppointment = filteritem[0].IsInsuranceConnectedAppointment;
                    }
                })
            }
        } else {
            $scope.SelectedPrimaryInsurance = ""; $scope.SelectedsecondaryInsurance = ""; $scope.SelectedOtherInsurance = "";
            $scope.ShowHideInsuranceobj.IsPrimaryInsuranceInd = false; $scope.ShowHideInsuranceobj.IsSecondaryInsuranceInd = false; $scope.ShowHideInsuranceobj.IsotherInsuranceInd = false;
        }
    }
