    $scope.onInsuranceSelect = function (val, item) {
        $scope.AddInsuranceToAppt = $scope.AddInsuranceToAppt || [];
        if (val === 1) {
            $scope.ValidateSelectedSlotAgainstPayor();
        }

        // Limit insurance count to 3 (1 primary, 1 secondary, 1 other)
        let MaxThreeLimit = $filter('filter')($scope.AddInsuranceToAppt, function (sitem) {
            return (sitem.DeleteInd == 'N' && sitem.IdentifierId != 0)
        });
        if (MaxThreeLimit.length >= 4) {
            alertify.error("Max limit reached for insurance");
            return false;
        }
        // Initialize IdentifierId
        let IdentifierId;
        //if (val === 1) {
        //    IdentifierId = 1;
        //    // Validate primary insurance selection
        //    if (!$scope.SelectedPrimaryInsurance) {
        //        alertify.error("Please select primary insurance!");
        //        return;
        //    }
        //} else if (val === 2) {
        //    IdentifierId = 2;
        //    // Validate secondary insurance selection
        //    if (!$scope.SelectedsecondaryInsurance) {
        //        alertify.error("Please select secondary insurance!");
        //        return;
        //    }
        //    if ($scope.AddInsuranceToAppt.length === 0 || !$scope.AddInsuranceToAppt.some(t => t.IdentifierId === 1)) {
        //        alertify.error("Please add primary insurance.");
        //        $scope.SelectedsecondaryInsurance = "";
        //        return false;
        //    }
        //} else if (val === 3) {
        //    IdentifierId = 5;
        //    // Validate other insurance selection
        //    if (!$scope.SelectedOtherInsurance) {
        //        alertify.error("Please select other insurance!");
        //        return;
        //    }
        //    if ($scope.AddInsuranceToAppt.length === 0 || !$scope.AddInsuranceToAppt.some(t => t.IdentifierId === 1)) {
        //        alertify.error("Please add primary insurance.");
        //        $scope.SelectedOtherInsurance = "";
        //        return false;
        //    }
        //    if (!$scope.AddInsuranceToAppt.some(s => s.IdentifierId === 2)) {
        //        alertify.error("Please add secondary insurance.");
        //        $scope.SelectedOtherInsurance = "";
        //        return false;
        //    }
        //}
        // Check for duplicates across different insurance types
        //if ($scope.AddInsuranceToAppt.some(t => t.PatientInsuranceDetailId === item.PatientInsuranceDetailId && t.DeleteInd == 'N')) {
        //    if (val == 1) {
        //        $scope.SelectedPrimaryInsurance = "";
        //        alertify.error("This insurance is already added as Seconday or Other");
        //    } else if (val == 2) {
        //        $scope.SelectedsecondaryInsurance = "";
        //        alertify.error("This insurance is already added as Primary or Other");
        //    } else if (val == 3) {
        //        $scope.SelectedOtherInsurance = "";
        //        alertify.error("This insurance is already added as Primary or Seconday");
        //    }
        //    return false;
        //}
        // Check if the insurance is already added
        const existingIndex = $scope.AddInsuranceToAppt.findIndex(t => t.PatientInsuranceDetailId === item.PatientInsuranceDetailId);
        if (existingIndex !== -1) {
            // Update the existing entry
            $scope.AddInsuranceToAppt[existingIndex] = {
                "PatientAppointmentInsuranceDetailId": item.PatientAppointmentInsuranceDetailId || 0,
                "PatientInsuranceDetailId": item.PatientInsuranceDetailId || null,
                "PayorId": item.PayorId,
                "OrganizationPayorId": item.OrganizationPayorId,
                "PlanId": item.PlanId,
                "CoverageId": item.CoverageId,
                "IdentifierId": IdentifierId,
                "PayorName": item.PayorName,
                "StatusId": item.StatusId,
                "DeleteInd": "N"
            };
        } else {
            // Add new insurance if not already added
            let reqObj = {
                "PatientAppointmentInsuranceDetailId": item.PatientAppointmentInsuranceDetailId || 0,
                "PatientInsuranceDetailId": item.PatientInsuranceDetailId || null,
                "PayorId": item.PayorId,
                "OrganizationPayorId": item.OrganizationPayorId,
                "PlanId": item.PlanId,
                "CoverageId": item.CoverageId,
                "IdentifierId": IdentifierId,
                "PayorName": item.PayorName,
                "StatusId": item.StatusId,
                "DeleteInd": "N"
            };
            $scope.AddInsuranceToAppt.push(reqObj);
            /*  item.IdentifierId = IdentifierId;*/
        }
        $scope.paymentTypeObj.IsPaymentTypeInd = false;
        // Update the UI state based on insurance type
        if (val === 1) {
            $scope.ShowHideInsuranceobj.IsPrimaryInsuranceInd = true;
            $scope.ShowHideInsuranceobj.PrimaryInusrancePlanName = item.PlanName;
            $scope.ShowHideInsuranceobj.PrimaryInusrancePolicyId = item.PolicyId;
            $scope.ShowHideInsuranceobj.PrimaryInusranceCoverage = item.PayorName;
            $scope.ShowHideInsuranceobj.PrimaryInusranceGroupId = item.GroupId;
        } else if (val === 2) {
            $scope.ShowHideInsuranceobj.IsSecondaryInsuranceInd = true;
            $scope.ShowHideInsuranceobj.SecondInusrancePlanName = item.PlanName;
            $scope.ShowHideInsuranceobj.SecondInusrancePolicyId = item.PolicyId;
            $scope.ShowHideInsuranceobj.SecondInusranceCoverage = item.PayorName;
            $scope.ShowHideInsuranceobj.SecondInusranceGroupId = item.GroupId;
        } else if (val === 3) {
            $scope.ShowHideInsuranceobj.IsotherInsuranceInd = true;
            $scope.ShowHideInsuranceobj.OtherInusrancePlanName = item.PlanName;
            $scope.ShowHideInsuranceobj.OtherInusrancePolicyId = item.PolicyId;
            $scope.ShowHideInsuranceobj.OtherInusranceCoverage = item.PayorName;
            $scope.ShowHideInsuranceobj.OtherInusranceGroupId = item.GroupId;
        }
    };
