    $scope.deleteInsurance = function (type, insuranceitem) {
        if (type == 1) {
            $scope.ShowHideInsuranceobj.IsPrimaryInsuranceInd = false;
            $scope.SelectedPrimaryInsurance = '';
        } else if (type == 2) {
            $scope.ShowHideInsuranceobj.IsSecondaryInsuranceInd = false;
            $scope.SelectedsecondaryInsurance = '';
        } else if (type == 3) {
            $scope.ShowHideInsuranceobj.IsotherInsuranceInd = false;
            $scope.SelectedOtherInsurance = '';
        }
        if ($scope.AddInsuranceToAppt.length > 0) {
            $scope.AddInsuranceToAppt.forEach((item, index) => {
                if (item.PatientInsuranceDetailId === insuranceitem.PatientInsuranceDetailId && item.PatientAppointmentInsuranceDetailId === 0) {
                    $scope.AddInsuranceToAppt.splice(index, 1); // Remove the item at the current index
                }
                if ((item.PatientInsuranceDetailId == insuranceitem.PatientInsuranceDetailId) && (item.PatientAppointmentInsuranceDetailId != 0)) {
                    item.DeleteInd = "Y";
                    /*item.IdentifierId = null;*/
                }
            });
        }
    };
