    $scope.DeleteInsuranceAppt = function (InsuranceItem) {
        if (InsuranceItem.PatientInsuranceDetailId != 0) {
            InsuranceItem.DeleteInd = 'Y';
        } else {
            let index = $scope.InsuranceList.PatientInsuranceDetails.indexOf(InsuranceItem);
            if (index > -1) {
                $scope.InsuranceList.PatientInsuranceDetails.splice(index, 1);
            }
        }
        if ($scope.AddInsuranceToAppt.length > 0) {
            angular.forEach($scope.AddInsuranceToAppt, function (item) {
                if (item.PatientInsuranceDetailId == InsuranceItem.PatientInsuranceDetailId) {
                    item.DeleteInd = 'Y';
                }
            });
        }
    }
