    $scope.GetAllUsers = function (id) {

        var subSplArray = _.pluck($scope.allSubSpecializationsArray, "SubSpecializationId").join(",");

        var HospitalId = 0;
        id = id || 0;
        if (id == 0) {
            HospitalId = $scope.HospitalId;
        } else {
            HospitalId = id;
        }

        var reqObj = {
            "BranchId": HospitalId || 0,
            "SubSpecializationIdArray": subSplArray
        }

        eHnoteMainAppointmentService.getAllUsersByDepartmentId(reqObj, onGetUsersSuccess, onGetUsersFailure);
        function onGetUsersSuccess(resp) {
            if (resp.rows.length > 0) {

                var UsersList = [];
                UsersList = resp.rows || [];
                if (UsersList.length > 0) {
                    $scope.clinicDoctorList = [];
                    angular.forEach(UsersList, function (Aitem) {
                        if (Aitem.RoleId === 1 || Aitem.RoleId === 43) {
                            $scope.clinicDoctorList.push(Aitem);
                        }
                    });
                }
                $scope.clinicDoctorList = _.uniq($scope.clinicDoctorList, false, function (p) { return p.DoctorID; });

            } else {
                alertify.error("No Users Found in Selected Departments");
                $scope.clinicDoctorList = [];

            }
        }

        function onGetUsersFailure(data) {
        }
    };

    $scope.ChangeLocation = function (H_id) {
        // $scope.GetOrganizationFacilityData(H_id);
        $scope.GetAllUsers(H_id);
        $scope.GetVisitReasonNew('', H_id);
        if (H_id != $scope.HospitalId) {
            $scope.IsBranchChanged = true;
            ChangedBranchId = H_id
        } else {
            $scope.IsBranchChanged = false;
            ChangedBranchId = angular.copy($scope.HospitalId) || 0;
        }

        $scope.selectedAppointmentObject.DocObj = '';
        $scope.selectedAppointmentObject.DoctorID = 0;
        $scope.selectedAppointmentObject.VisitReasonObj = '';
        $scope.selectedAppointmentObject.VisitReasonId = 0;
        $scope.selectedAppointmentObject.OrganizationFacilityId = 0;

        // Location determines which doctor/schedule slots apply — clear the previously
        // selected slot so a stale one from another location can't carry over.
        $scope.selectedAppointmentObject.StartTime = "";
        $scope.selectedAppointmentObject.patinet_appStarttime = "";
        $scope.selectedAppointmentObject.patient_appEndTime = "";
        $scope.selectedAppointmentObject.TimeSlotsStartArray = [];
        $scope.selectedAppointmentObject.TimeSlotsEndArray = [];
        if ($scope.Doctorcalendarobj && $scope.Doctorcalendarobj != '') {
            $scope.Doctorcalendarobj.Starttime = "";
            $scope.Doctorcalendarobj.IsComingFrom = "";
        }
        if (AppointmentDetailsCache && AppointmentDetailsCache.IsComingFrom == "IsCalenderUnavalableslot") {
            // Same cache GetUserActiveDatesandSlotsInCalendar force-overwrites DoctorID/DocObj from —
            // clear it here too, since Location change already resets DocObj/DoctorID above.
            AppointmentDetailsCache.IsComingFrom = "";
        }
        $scope.isAppValiddities.isEnableAlertType = false;
        $scope.isAppValiddities.IsEnabledAfterCheckHere = false;
    }

